package ro.leo.visual;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.pdf.PdfDocument;
import android.os.*;import android.view.*;import android.widget.*;import android.service.notification.StatusBarNotification;
import java.io.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;

/** Private document/image fixtures and a local notification; never sends SMS or calls. */
public final class DailyExperienceTests extends Instrumentation {
    private int checks;private Activity page;
    private void check(boolean yes,String why){if(!yes)throw new AssertionError(why);checks++;}
    private Object field(Object target,String name)throws Exception{Class<?> k=target.getClass();while(k!=null){try{java.lang.reflect.Field f=k.getDeclaredField(name);f.setAccessible(true);return f.get(target);}catch(NoSuchFieldException missing){k=k.getSuperclass();}}throw new NoSuchFieldException(name);}
    private void call(final Object target,String name)throws Exception{final java.lang.reflect.Method m=target.getClass().getDeclaredMethod(name);m.setAccessible(true);runOnMainSync(new Runnable(){public void run(){try{m.invoke(target);}catch(Exception e){throw new RuntimeException(e);}}});waitForIdleSync();}
    private void close(){if(page!=null){final Activity old=page;runOnMainSync(new Runnable(){public void run(){old.finish();}});page=null;waitForIdleSync();}}
    private void open(Class<?> type,File file){close();Intent i=new Intent(getTargetContext(),type).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);if(file!=null)i.putExtra("file",file.getAbsolutePath());page=startActivitySync(i);runOnMainSync(new Runnable(){public void run(){page.getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON|WindowManager.LayoutParams.FLAG_TURN_SCREEN_ON);}});waitForIdleSync();}
    private void await(final String kind)throws Exception{long until=SystemClock.uptimeMillis()+15000;while(SystemClock.uptimeMillis()<until){final boolean[] ready={false};runOnMainSync(new Runnable(){public void run(){try{if(kind.equals("pdf")){View canvas=(View)field(page,"canvas");ready[0]=canvas!=null&&canvas.getParent()==((LeoActivity)page).root&&field(page,"bitmap")!=null;}else if(kind.equals("reader"))ready[0]=field(page,"body")!=null;else if(kind.equals("photo"))ready[0]=field(page,"photo")!=null;else ready[0]=!((Map<?,?>)field(page,"thumbs")).isEmpty();}catch(Exception ignored){}}});if(ready[0])return;SystemClock.sleep(100);}throw new AssertionError("Timed out: "+kind);}
    private void capture(String name)throws Exception{Bitmap shot=getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES).takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name))){shot.compress(Bitmap.CompressFormat.PNG,100,out);}finally{shot.recycle();}}
    private ListView list(View v){if(v instanceof ListView)return (ListView)v;if(v instanceof ViewGroup)for(int n=0;n<((ViewGroup)v).getChildCount();n++){ListView found=list(((ViewGroup)v).getChildAt(n));if(found!=null)return found;}return null;}
    private EditText editor(View v){if(v instanceof EditText)return (EditText)v;if(v instanceof ViewGroup)for(int n=0;n<((ViewGroup)v).getChildCount();n++){EditText e=editor(((ViewGroup)v).getChildAt(n));if(e!=null)return e;}return null;}
    private void restore(SharedPreferences p,Map<String,?> values){SharedPreferences.Editor e=p.edit().clear();for(Map.Entry<String,?> v:values.entrySet()){Object o=v.getValue();if(o instanceof Integer)e.putInt(v.getKey(),(Integer)o);else if(o instanceof Long)e.putLong(v.getKey(),(Long)o);else if(o instanceof Boolean)e.putBoolean(v.getKey(),(Boolean)o);else if(o instanceof String)e.putString(v.getKey(),(String)o);else if(o instanceof Set)e.putStringSet(v.getKey(),new HashSet<String>((Set<String>)o));}e.commit();}
    public void onCreate(Bundle b){start();}
    public void onStart(){Bundle result=new Bundle();Context c=getTargetContext();String token="leo14-"+UUID.randomUUID();File dir=new File(c.getFilesDir(),"documents");dir.mkdirs();File md=new File(dir,token+".md"),pdf=new File(dir,token+".pdf"),png=new File(dir,token+".png");String[] stores={"reader","pdf-reader","home-long-keys"};ArrayList<Map<String,?>> saved=new ArrayList<>();for(String store:stores)saved.add(new HashMap<>(c.getSharedPreferences(store,0).getAll()));
        try{
            check(DailyAgendaActivity.pending("[ ] First\n[x] Done\nPlain\n[ ] Second").equals(Arrays.asList("First","Second")),"agenda includes only unchecked tasks");
            check(DailyAgendaActivity.pending("[ ]   \n[x] Done").isEmpty(),"empty tasks excluded");
            check(DailyAgendaActivity.read(c,System.currentTimeMillis()).size()>=2,"daily overview includes calendar and next alarm routes");
            check(HomeKeyActions.app(c,0)==-1&&HomeKeyActions.app(c,1)==-1&&!HomeKeyActions.configurable(10),"reserved keys protected");
            boolean denied=false;try{HomeKeyActions.save(c,1,4);}catch(IllegalArgumentException e){denied=true;}check(denied,"reserved key writes rejected");
            HomeKeyActions.save(c,2,4);check(HomeKeyActions.app(c,2)==4,"long key assignment persists");HomeKeyActions.save(c,2,-1);check(HomeKeyActions.app(c,2)==-1,"speed dial restored without deleting number");
            check(ContactTimelineActivity.matches(Arrays.asList("+40 700 123 456"),"0700123456"),"contact matching accepts national and international forms");
            check(!ContactTimelineActivity.matches(Arrays.asList("0700123456"),"0700654321"),"other contact excluded");
            check(ContactTimelineActivity.read(c,-1).isEmpty(),"contact without numbers has no mixed history");
            int[] dims=PdfReaderActivity.dimensions(6000,9000);check(dims[0]>0&&dims[1]>0&&dims[0]*dims[1]<=1048576&&dims[1]<=1536,"PDF bitmap bounded");
            check(MarkdownText.display("# Heading\n- Item\n```\ncode\n```").toString().startsWith("Heading\n• Item"),"Markdown headings and bullets styled locally");
            try(FileOutputStream out=new FileOutputStream(md)){out.write("# Local reading fixture\n\n- First item\nA needle in this document.\n".getBytes("UTF-8"));}
            check(BookDocument.read(md).chapters.get(0).contains("needle"),"Markdown accepted by book parser");check(ReaderActivity.findText("İ hereX","X",0)==6&&ReaderActivity.findText("AbC","bc",0)==1,"text search preserves Unicode offsets");check(BackupEngine.allowed("home-long-keys","app2","int")&&!BackupEngine.allowed("home-long-keys","app1","int")&&BackupEngine.allowed("accessibility","repeat","int"),"backup retains configurable keys and repeat preference only");
            open(ReaderActivity.class,md);await("reader");check(((TextView)field(page,"body")).getText().toString().startsWith("Local reading fixture"),"reader renders Markdown without heading markers");capture("leo14-markdown.png");call(page,"search");runOnMainSync(new Runnable(){public void run(){editor(((LeoActivity)page).root).setText("needle");((LeoActivity)page).left.run();}});waitForIdleSync();check(list(((LeoActivity)page).root).getAdapter().getCount()==1,"reader search finds local document match");SystemClock.sleep(350);sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);waitForIdleSync();check((Integer)field(page,"offset")>0,"search selection opens matching offset");close();
            PdfDocument document=new PdfDocument();try{for(int n=1;n<=2;n++){PdfDocument.Page p=document.startPage(new PdfDocument.PageInfo.Builder(240,320,n).create());Paint ink=new Paint();ink.setColor(Color.BLACK);ink.setTextSize(18);p.getCanvas().drawText("Leo PDF fixture "+n,15,40,ink);ink.setColor(0xff00aa99);p.getCanvas().drawCircle(120,140,50,ink);document.finishPage(p);}try(FileOutputStream out=new FileOutputStream(pdf)){document.writeTo(out);}}finally{document.close();}
            open(PdfReaderActivity.class,pdf);await("pdf");check((Integer)field(page,"count")==2,"native renderer opens two-page PDF");
            sendKeyDownUpSync(KeyEvent.KEYCODE_6);waitForIdleSync();await("pdf");check((Integer)field(page,"page")==1,"6 advances PDF page");
            sendKeyDownUpSync(KeyEvent.KEYCODE_9);waitForIdleSync();check((Integer)field(page,"zoom")==2,"9 zooms PDF");capture("leo14-pdf.png");close();
            open(PdfReaderActivity.class,pdf);await("pdf");check((Integer)field(page,"page")==1,"PDF resumes saved page");close();
            Bitmap image=Bitmap.createBitmap(120,120,Bitmap.Config.ARGB_8888);image.eraseColor(0xff00a899);try(FileOutputStream out=new FileOutputStream(png)){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();
            page=startActivitySync(new Intent(c,GalleryActivity.class).setData(LeoFileProvider.uri(c,png)).putExtra("title","Local gallery fixture").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));runOnMainSync(new Runnable(){public void run(){page.getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON|WindowManager.LayoutParams.FLAG_TURN_SCREEN_ON);}});await("photo");
            sendKeyDownUpSync(KeyEvent.KEYCODE_9);waitForIdleSync();check((Integer)field(page,"zoom")==2,"gallery zoom uses physical key");
            call(page,"grid");await("thumbs");Bitmap first=(Bitmap)((Map<?,?>)field(page,"thumbs")).get(0);call(page,"grid");await("thumbs");check(first==((Map<?,?>)field(page,"thumbs")).get(0)&&!first.isRecycled(),"gallery reuses cached thumbnail without recycling visible image");close();
            notifications(c,token);
            open(DailyAgendaActivity.class,null);check(!page.isFinishing(),"daily overview opens from shell route");close();open(LongPressSettingsActivity.class,null);check(!page.isFinishing(),"long press settings opens");close();
            result.putString("result","PASS "+checks+" daily experience checks");
        }catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));}
        finally{close();for(int n=0;n<stores.length;n++)restore(c.getSharedPreferences(stores[n],0),saved.get(n));md.delete();pdf.delete();png.delete();}
        finish(result.containsKey("error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);
    }
    private void notifications(final Context c,String token)throws Exception{
        final AtomicReference<String> received=new AtomicReference<>();String action="ro.leo.visual.LOCAL_REPLY_"+token;BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){Bundle b=RemoteInput.getResultsFromIntent(i);received.set(b==null?null:b.getCharSequence("reply").toString());}};c.registerReceiver(receiver,new IntentFilter(action));NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);PendingIntent intent=PendingIntent.getBroadcast(c,7414,new Intent(action).setPackage(c.getPackageName()),PendingIntent.FLAG_UPDATE_CURRENT);String key=null;
        try{nm.createNotificationChannel(new NotificationChannel(token,"Local Leo fixture",NotificationManager.IMPORTANCE_LOW));RemoteInput input=new RemoteInput.Builder("reply").setLabel("Local reply").build();Notification.Action reply=new Notification.Action.Builder(null,"Local reply",intent).addRemoteInput(input).build();Notification notification=new Notification.Builder(c,token).setSmallIcon(android.R.drawable.ic_dialog_info).setCategory(Notification.CATEGORY_REMINDER).setContentTitle("Local notification fixture").addAction(reply).build();nm.notify(token,7414,notification);
            if(LeoNotificationService.active==null)LeoNotificationService.reconnect(c);StatusBarNotification fixture=null;long until=SystemClock.uptimeMillis()+15000;while(fixture==null&&SystemClock.uptimeMillis()<until){for(StatusBarNotification n:LeoNotificationService.snapshot())if(token.equals(n.getTag()))fixture=n;if(fixture==null)SystemClock.sleep(100);}check(fixture!=null,"listener receives local interactive notification");key=fixture.getKey();
            Intent fill=new Intent();Bundle answer=new Bundle();answer.putCharSequence("reply","Local reply fixture");RemoteInput.addResultsToIntent(new RemoteInput[]{input},fill,answer);reply.actionIntent.send(c,0,fill);until=SystemClock.uptimeMillis()+3000;while(received.get()==null&&SystemClock.uptimeMillis()<until)SystemClock.sleep(50);check("Local reply fixture".equals(received.get()),"RemoteInput reaches only local fixture receiver");
            check(LeoNotificationService.canSnooze(fixture)&&!LeoNotificationService.snooze(fixture,999),"snooze validates duration");check(LeoNotificationService.snooze(fixture,60000),"listener accepts snooze for local reminder");
            boolean present=true;until=SystemClock.uptimeMillis()+3000;while(present&&SystemClock.uptimeMillis()<until){present=false;for(StatusBarNotification n:LeoNotificationService.snapshot())if(key.equals(n.getKey()))present=true;if(present)SystemClock.sleep(50);}check(!present,"snoozed fixture leaves active notifications");
        }finally{nm.cancel(token,7414);nm.deleteNotificationChannel(token);intent.cancel();c.unregisterReceiver(receiver);}
    }
}
